import {
    AdapterState,
    isInBrowser,
    WalletReadyState,
    WalletSignMessageError,
    WalletNotFoundError,
    WalletDisconnectedError,
    WalletConnectionError,
    WalletSignTransactionError,
    WalletSignTypedDataError,
    WalletSwitchChainError,
    WalletGetNetworkError,
    isInMobileBrowser,
    NetworkType,
    AddonAdapter,
    WalletError,
    TIP6963AnnounceProviderEventName,
    TIP6963RequestProviderEventName,
} from '@tronweb3/tronwallet-abstract-adapter';
import type {
    Transaction,
    SignedTransaction,
    AdapterName,
    BaseAdapterConfig,
    Network,
    TypedData,
    TIP6963AnnounceProviderEvent,
} from '@tronweb3/tronwallet-abstract-adapter';
import type {
    ReqestAccountsResponse,
    Tron,
    TronAccountsChangedCallback,
    TronChainChangedCallback,
    TronWeb,
} from './types.js';
import { openTronLink, supportTron, waitTronwebReady } from './utils.js';
export interface TronLinkWallet {
    ready: boolean;
    tronWeb: TronWeb;
    request(config: Record<string, unknown>): Promise<ReqestAccountsResponse | null>;
}
export const chainIdNetworkMap: Record<string, NetworkType> = {
    '0x2b6653dc': NetworkType.Mainnet,
    '0x94a9059e': NetworkType.Shasta,
    '0xcd8690dc': NetworkType.Nile,
};

export async function getNetworkInfoByTronWeb(tronWeb: TronWeb) {
    const { blockID = '' } = await tronWeb.trx.getBlockByNumber(0);
    const chainId = `0x${blockID.slice(-8)}`;
    return {
        networkType: chainIdNetworkMap[chainId] || NetworkType.Unknown,
        chainId,
        fullNode: tronWeb.fullNode?.host || '',
        solidityNode: tronWeb.solidityNode?.host || '',
        eventServer: tronWeb.eventServer?.host || '',
    };
}
declare global {
    interface Window {
        tronLink?: TronLinkWallet;
        tronWeb?: TronWeb & { ready?: boolean };
        // @ts-ignore
        tron?: Tron;
    }
}
export interface TronLinkAdapterConfig extends BaseAdapterConfig {
    /**
     * Timeout in millisecond for checking if TronLink wallet exists.
     * Default is 5000ms
     */
    checkTimeout?: number;
    /**
     * Set if open TronLink app using DeepLink.
     * Default is true.
     */
    openAppWithDeeplink?: boolean;
    /**
     * @deprecated Please use `openAppWithDeeplink`
     */
    openTronLinkAppOnMobile?: boolean;
    /**
     * The icon of your dapp. Used when open TronLink app in mobile device browsers.
     */
    dappIcon?: string;
    /**
     * The name of your dapp. Used when open TronLink app in mobile device browsers.
     */
    dappName?: string;
}

export const TronLinkAdapterName = 'TronLink' as AdapterName<'TronLink'>;
const TRONLINK_RDNS = 'org.tronlink.www';

export class TronLinkAdapter extends AddonAdapter {
    name = TronLinkAdapterName;
    url = 'https://www.tronlink.org/';
    icon =
        'data:image/png;base64,';

    config: Required<TronLinkAdapterConfig>;
    private _readyState: WalletReadyState = isInBrowser() ? WalletReadyState.Loading : WalletReadyState.NotFound;
    private _state: AdapterState = isInBrowser() ? AdapterState.Loading : AdapterState.NotFound;
    private _connecting: boolean;
    private _wallet: TronLinkWallet | Tron | null;
    private _address: string | null;
    // https://github.com/tronprotocol/tips/blob/master/tip-1193.md
    private _supportNewTronProtocol = false;
    // record if first connect event has emitted or not

    constructor(config: TronLinkAdapterConfig = {}) {
        super(config);
        const {
            checkTimeout = 5 * 1000,
            dappIcon = '',
            dappName = '',
            openUrlWhenWalletNotFound = true,
            openTronLinkAppOnMobile = true,
            openAppWithDeeplink = true,
        } = config;
        if (typeof checkTimeout !== 'number') {
            throw new Error('[TronLinkAdapter] config.checkTimeout should be a number');
        }
        this.config = {
            ...this.commonConfig,
            checkTimeout,
            openTronLinkAppOnMobile,
            openAppWithDeeplink,
            openUrlWhenWalletNotFound,
            dappIcon,
            dappName,
        };
        this._connecting = false;
        this._wallet = null;
        this._address = null;

        if (!isInBrowser()) {
            this._readyState = WalletReadyState.NotFound;
            this.setState(AdapterState.NotFound);
            return;
        }
        if (!isInMobileBrowser()) {
            this._checkWallet().then(() => {
                if (this.connected) {
                    this.emit('connect', this.address || '');
                }
            });
        } else if (supportTron() || (isInMobileBrowser() && (window.tronLink || window.tronWeb))) {
            this._readyState = WalletReadyState.Found;
            this._updateWallet().then(() => {
                if (this.connected) {
                    this.emit('connect', this.address || '');
                }
            });
        } else {
            this._checkWallet().then(() => {
                if (this.connected) {
                    this.emit('connect', this.address || '');
                }
            });
        }
    }

    get address() {
        return this._address;
    }

    get state() {
        return this._state;
    }
    get readyState() {
        return this._readyState;
    }

    get connecting() {
        return this._connecting;
    }

    /**
     * Get network information used by TronLink.
     * @returns {Network} Current network information.
     */
    async network(): Promise<Network> {
        try {
            await this._checkWallet();
            if (this.state !== AdapterState.Connected) throw new WalletDisconnectedError();
            const tronWeb = this._wallet?.tronWeb || window.tronWeb;
            if (!tronWeb) throw new WalletDisconnectedError();
            try {
                return await getNetworkInfoByTronWeb(tronWeb);
            } catch (e: any) {
                throw new WalletGetNetworkError(e?.message, e);
            }
        } catch (e: any) {
            this.emit('error', e);
            throw e;
        }
    }

    async connect(): Promise<void> {
        try {
            if (!(await this._beforeConnect())) return;
            // lower version only support window.tronWeb, no window.tronLink
            if (!this._wallet) return;
            this._connecting = true;
            if (this._supportNewTronProtocol) {
                const wallet = this._wallet as Tron;
                try {
                    const res = await wallet.request({ method: 'eth_requestAccounts' });
                    const address = res[0];
                    this.setAddress(address);
                    this.setState(AdapterState.Connected);
                    this._listenTronEvent();
                    if (!this._wallet.tronWeb) {
                        await waitTronwebReady(this._wallet as Tron);
                    }
                } catch (error: any) {
                    let message = error?.message || error || 'Connect TronLink wallet failed.';
                    if (error.code === -32002) {
                        message =
                            'The same DApp has already initiated a request to connect to TronLink wallet, and the pop-up window has not been closed.';
                    }
                    if (error.code === 4001) {
                        message = 'The user rejected connection.';
                    }
                    throw new WalletConnectionError(message, error);
                }
            } else if (window.tronLink) {
                const wallet = this._wallet as TronLinkWallet;
                const res = await wallet.request({ method: 'tron_requestAccounts' });
                if (!res) {
                    // 1. wallet is locked
                    // 2. tronlink is first installed and there is no wallet account
                    throw new WalletConnectionError('TronLink wallet is locked or no wallet account is avaliable.');
                }
                if (res.code === 4000) {
                    throw new WalletConnectionError(
                        'The same DApp has already initiated a request to connect to TronLink wallet, and the pop-up window has not been closed.'
                    );
                }
                if (res.code === 4001) {
                    throw new WalletConnectionError('The user rejected connection.');
                }

                const address = wallet.tronWeb.defaultAddress?.base58 || '';
                this.setAddress(address);
                this.setState(AdapterState.Connected);
            } else if (window.tronWeb) {
                const wallet = this._wallet as TronLinkWallet;
                const address = wallet.tronWeb.defaultAddress?.base58 || '';
                this.setAddress(address);
                this.setState(AdapterState.Connected);
            } else {
                throw new WalletConnectionError('Cannot connect wallet.');
            }
            this.connected && this.emit('connect', this.address || '');
        } catch (error: any) {
            const err = error instanceof WalletError ? error : new WalletConnectionError(error?.message, error);
            this.emit('error', err);
            throw err;
        } finally {
            this._connecting = false;
        }
    }

    async disconnect(): Promise<void> {
        if (this._supportNewTronProtocol) {
            this._stopListenTronEvent();
        }
        if (this.state !== AdapterState.Connected) {
            return;
        }
        this.setAddress(null);
        this.setState(AdapterState.Disconnect);
        this.emit('disconnect');
    }

    private async _checkAndSign<T>(
        action: (wallet: Tron & { tronWeb: TronWeb }) => Promise<T>,
        ErrorConstructor: typeof WalletSignTransactionError | typeof WalletSignMessageError
    ): Promise<T> {
        try {
            const wallet = await this.checkAndGetWallet();
            try {
                return await action(wallet);
            } catch (error: any) {
                if (error instanceof Error || (typeof error === 'object' && error.message)) {
                    throw new ErrorConstructor(error.message, error);
                } else if (typeof error === 'string') {
                    throw new ErrorConstructor(error, new Error(error));
                } else {
                    throw new ErrorConstructor('Unknown error', error);
                }
            }
        } catch (error: any) {
            this.emit('error', error);
            throw error;
        }
    }

    async signTransaction(transaction: Transaction): Promise<SignedTransaction> {
        return this._checkAndSign((wallet) => wallet.tronWeb.trx.sign(transaction), WalletSignTransactionError);
    }

    /**
     *
     * @param transaction transaction to be signed
     * @param _, false to use tronWeb.trx.multiSign
     * @param permissionId permissionId for multiSign
     * @returns
     */
    async multiSign(transaction: Transaction, options: { permissionId?: number } = {}): Promise<SignedTransaction> {
        // multiSign is a transaction signing operation, so it uses WalletSignTransactionError
        return this._checkAndSign(
            (wallet) => wallet.tronWeb.trx.multiSign(transaction, undefined, options.permissionId),
            WalletSignTransactionError
        );
    }

    async signMessage(message: string): Promise<string> {
        return this._checkAndSign(async (wallet) => wallet.tronWeb.trx.signMessageV2(message), WalletSignMessageError);
    }

    protected async _signTypedData(typedData: TypedData): Promise<string> {
        return this._checkAndSign(
            async (wallet) => wallet.tronWeb.trx._signTypedData(typedData.domain, typedData.types, typedData.message),
            WalletSignTypedDataError
        );
    }

    /**
     * Switch to target chain. If current chain is the same as target chain, the call will success immediately.
     * Available chainIds:
     * - Mainnet: 0x2b6653dc
     * - Shasta: 0x94a9059e
     * - Nile: 0xcd8690dc
     * @param chainId chainId
     */
    async switchChain(chainId: string) {
        try {
            await this._checkWallet();
            if (this.state === AdapterState.NotFound) {
                if (this.config.openUrlWhenWalletNotFound !== false && isInBrowser()) {
                    window.open(this.url, '_blank');
                }
                throw new WalletNotFoundError();
            }
            if (!this._supportNewTronProtocol) {
                throw new WalletSwitchChainError("Current version of TronLink doesn't support switch chain operation.");
            }
            const wallet = this._wallet as Tron;
            try {
                await wallet.request({
                    method: 'wallet_switchEthereumChain',
                    params: [{ chainId }],
                });
            } catch (e: any) {
                throw new WalletSwitchChainError(e?.message || e, e instanceof Error ? e : new Error(e));
            }
        } catch (error: any) {
            this.emit('error', error);
            throw error;
        }
    }

    private async checkAndGetWallet() {
        if (this._openAppByDeepLinkIfNeed()) {
            throw new WalletNotFoundError();
        }
        await this._checkWallet();
        if (this.state !== AdapterState.Connected) throw new WalletDisconnectedError();
        const wallet = this._wallet;
        if (!wallet || !wallet.tronWeb) throw new WalletDisconnectedError();
        return wallet as Tron & { tronWeb: TronWeb };
    }

    protected _openAppByDeepLinkIfNeed(): boolean {
        if (this.config.openAppWithDeeplink === false || this.config.openTronLinkAppOnMobile === false) {
            return false;
        }
        const { dappName = '', dappIcon = '' } = this.config;
        return openTronLink({ dappIcon, dappName });
    }
    // following code is for TIP-1193
    private _listenTronEvent() {
        this._stopListenTronEvent();
        const wallet = this._wallet as Tron;
        wallet.on?.('chainChanged', this._onChainChanged);
        wallet.on?.('accountsChanged', this._onAccountsChanged);
    }

    private _stopListenTronEvent() {
        const wallet = this._wallet as Tron;
        wallet.removeListener?.('chainChanged', this._onChainChanged);
        wallet.removeListener?.('accountsChanged', this._onAccountsChanged);
    }

    private _onChainChanged: TronChainChangedCallback = (data) => {
        this.emit('chainChanged', data);
    };

    private _onAccountsChanged: TronAccountsChangedCallback = () => {
        const preAddr = this.address || '';
        const curAddr = (this._wallet?.tronWeb && this._wallet?.tronWeb.defaultAddress?.base58) || '';
        this.setAddress(curAddr ? curAddr : null);
        this.setState(this.address ? AdapterState.Connected : AdapterState.Disconnect);
        this.emit('accountsChanged', this.address || '', preAddr);
        if (!preAddr && this.address) {
            this.emit('connect', this.address);
        } else if (preAddr && !this.address) {
            this.emit('disconnect');
        }
    };

    private _checkPromise: Promise<boolean> | null = null;
    private isLegacyTronLinkProvider(provider: Tron | undefined | null) {
        return !!provider?.isTronLink;
    }

    private hasDesktopLegacyTronLinkProvider() {
        return this.isLegacyTronLinkProvider(window.tron) || !!window.tronLink;
    }
    /**
     * check if wallet exists by interval, the promise only resolve when wallet detected or timeout
     * @returns if wallet exists
     */
    protected _checkWallet(): Promise<boolean> {
        if (this.readyState === WalletReadyState.Found) {
            return Promise.resolve(true);
        }
        if (this._checkPromise) {
            return this._checkPromise;
        }

        if (isInBrowser() && !isInMobileBrowser()) {
            // Desktop: use TIP-6963 event-based discovery with fallback
            this._checkPromise = new Promise((resolve) => {
                let handled = false;
                let timer: ReturnType<typeof setTimeout> | null = null;
                let interval: ReturnType<typeof setInterval> | null = null;
                let handler: ((event: TIP6963AnnounceProviderEvent) => void) | null = null;

                const cleanupDesktopDetection = () => {
                    if (interval) {
                        clearInterval(interval);
                        interval = null;
                    }
                    if (timer) {
                        clearTimeout(timer);
                        timer = null;
                    }
                    if (typeof window !== 'undefined' && handler) {
                        window.removeEventListener(TIP6963AnnounceProviderEventName, handler);
                    }
                };

                const finishWithLegacyDetection = () => {
                    if (handled) {
                        return;
                    }
                    handled = true;
                    cleanupDesktopDetection();
                    if (typeof window === 'undefined') {
                        resolve(false);
                        return;
                    }
                    // Fallback to legacy detection
                    this._updateWallet();
                    const isSupport = this.state !== AdapterState.NotFound;
                    this._readyState = isSupport ? WalletReadyState.Found : WalletReadyState.NotFound;
                    this.emit('readyStateChanged', this._readyState);
                    resolve(isSupport);
                };

                timer = setTimeout(finishWithLegacyDetection, this.config.checkTimeout);

                handler = async (event: TIP6963AnnounceProviderEvent) => {
                    if (handled) {
                        return;
                    }
                    const { info, provider } = event.detail;
                    const isTronLinkProvider = info.name === 'TronLink';
                    if (isTronLinkProvider) {
                        handled = true;
                        this._supportNewTronProtocol = true;
                        this._wallet = provider as unknown as Tron;
                        try {
                            await this.checkSecurity();
                        } catch {
                            this.setAddress(null);
                            this.setState(AdapterState.Disconnect);
                            this._readyState = WalletReadyState.Found;
                            this.emit('readyStateChanged', this.readyState);
                            resolve(true);
                            return;
                        }
                        this._listenTronEvent();
                        this._readyState = WalletReadyState.Found;
                        const address =
                            (this._wallet?.tronWeb && (this._wallet.tronWeb as TronWeb).defaultAddress?.base58) || null;
                        const state = address ? AdapterState.Connected : AdapterState.Disconnect;
                        this.setAddress(address);
                        this.setState(state);
                        this.emit('readyStateChanged', this.readyState);
                        cleanupDesktopDetection();
                        resolve(true);
                    }
                };

                window.addEventListener(TIP6963AnnounceProviderEventName, handler);
                window.dispatchEvent(new Event(TIP6963RequestProviderEventName));
            });
            return this._checkPromise;
        }

        // Mobile: use legacy polling detection
        const interval = 100;
        const maxTimes = Math.floor(this.config.checkTimeout / interval);
        let times = 0,
            timer: ReturnType<typeof setInterval>;
        this._checkPromise = new Promise((resolve) => {
            const check = () => {
                times++;
                this._updateWallet();
                const isSupport = !!(isInMobileBrowser() && (window.tronLink || window.tronWeb));
                if (isSupport || times > maxTimes) {
                    timer && clearInterval(timer);
                    this._readyState = isSupport ? WalletReadyState.Found : WalletReadyState.NotFound;
                    this.emit('readyStateChanged', this.readyState);
                    resolve(isSupport);
                }
            };
            timer = setInterval(check, interval);
            check();
        });
        return this._checkPromise;
    }

    private _updateWallet = async () => {
        this._supportNewTronProtocol = false;
        let state = this.state;
        let address = this.address;
        if (isInMobileBrowser()) {
            if (window.tronLink) {
                this._wallet = window.tronLink;
            } else {
                this._wallet = {
                    ready: !!window.tronWeb?.defaultAddress,
                    tronWeb: window.tronWeb,
                    request: () => Promise.resolve(true) as any,
                } as TronLinkWallet;
            }
            address = this._wallet.tronWeb?.defaultAddress?.base58 || null;
            if (address) {
                // Only run the security check once the wallet is actually connected.
                try {
                    await this.checkSecurity();
                } catch {
                    this.setAddress(null);
                    this.setState(AdapterState.Disconnect);
                    return;
                }
                state = AdapterState.Connected;
            } else {
                state = AdapterState.Disconnect;
            }
        } else if (this.isLegacyTronLinkProvider(window.tron)) {
            this._supportNewTronProtocol = true;
            this._wallet = window.tron as Tron;
            this._listenTronEvent();
            try {
                address = (this._wallet?.tronWeb && this._wallet.tronWeb?.defaultAddress?.base58) || null;
                state = address ? AdapterState.Connected : AdapterState.Disconnect;
            } catch (e) {
                console.error('Unknown error: ' + e, ' Please install TronLink extension wallet.');
                address = null;
                state = AdapterState.Disconnect;
                this._readyState = WalletReadyState.NotFound;
                this.emit('readyStateChanged', this.readyState);
                return;
            }
        } else if (window.tronLink) {
            this._wallet = window.tronLink;
            address = this._wallet.tronWeb?.defaultAddress?.base58 || null;
            state = this._wallet.ready ? AdapterState.Connected : AdapterState.Disconnect;
        } else {
            // no tronlink support
            this._wallet = null;
            address = null;
            state = AdapterState.NotFound;
        }
        // In TronLink App, account should be connected
        if (isInMobileBrowser() && state === AdapterState.Disconnect) {
            this.checkForWalletReadyForApp();
        }
        this.setAddress(address);
        this.setState(state);
    };

    private checkReadyInterval: ReturnType<typeof setInterval> | null = null;
    private checkForWalletReadyForApp() {
        if (this.checkReadyInterval) {
            return;
        }
        let times = 0;
        const maxTimes = Math.floor(this.config.checkTimeout / 200);
        const check = () => {
            if (window.tronLink ? window.tronLink.tronWeb?.defaultAddress : window.tronWeb?.defaultAddress) {
                this.checkReadyInterval && clearInterval(this.checkReadyInterval);
                this.checkReadyInterval = null;
                this._updateWallet();
                this.emit('connect', this.address || '');
            } else if (times > maxTimes) {
                this.checkReadyInterval && clearInterval(this.checkReadyInterval);
                this.checkReadyInterval = null;
            } else {
                times++;
            }
        };
        this.checkReadyInterval = setInterval(check, 200);
    }
    private setAddress(address: string | null) {
        this._address = address;
    }

    private setState(state: AdapterState) {
        const preState = this.state;
        if (state !== preState) {
            this._state = state;
            this.emit('stateChanged', state);
        }
    }
}
